def solve(session,options):
    """Only scheduling and status decisions are on CPU; all solver arithmetic is PTX."""
    s=session;trace=[];restarts=0
    s.launch('element_probe');s.launch('assemble_probe')
    applied=s.read('applied')
    s.launch('initialize');s.launch('dot_rhs');s.launch('dot_rz');s.launch('start')
    rhs_norm=s.scalar('rhs_norm');tolerance=s.scalar('tolerance')
    residual=rhs_norm
    def finish(it,reason):
        return dict(solution=s.read('x'),applied=applied,iterations=it,reason=reason,converged=reason=='converged',
                    true_residual_norm=residual,relative_residual=residual/rhs_norm if rhs_norm else 0.,
                    tolerance=tolerance,restarts=restarts,checks=trace,storage_audit=s.audit_storage(),
                    launches=s.launch_log)
    if not math.isfinite(rhs_norm):return finish(0,'breakdown')
    if rhs_norm<=tolerance:return finish(0,'converged')
    maximum=options.get('maxiter',1000);interval=options.get('check_every',10)
    if maximum==0:return finish(0,'maxiter')
    for it in range(1,maximum+1):
        for name in ('element_p','assemble_ap','dot_pap','coefficient_alpha','update_xrz','dot_next','dot_rr','coefficient_beta','update_p'):
            s.launch(name)
        if it%interval==0 or it==maximum:
            for name in ('element_x','assemble_ap','true_residual','dot_true','residual_norm'):s.launch(name)
            residual=s.scalar('residual');active=s.scalar('active');broken=s.scalar('broken')
            trace.append(dict(iteration=it,residual=residual,active=bool(active),broken=bool(broken)))
            if not math.isfinite(residual):return finish(it,'breakdown')
            if residual<=tolerance:return finish(it,'converged')
            if broken:return finish(it,'breakdown')
            if not active:
                for name in ('restart_vectors','dot_rz','restart_flag'):s.launch(name)
                restarts+=1
    return finish(maximum,'maxiter')

class Layout:
    def __init__(self, reference, options):
        n,p=reference['n'],reference['degree']
        if type(n) is not int or n<1 or type(p) is not int or p not in (1,2,3,4):
            raise ValueError('expected positive n and degree 1..4')
        self.n,self.p,self.m=n,p,p+1
        self.size=(n*p+1)**2
        if self.size>=2**30 or n*n*(p+1)**2>=2**30:
            raise ValueError('index domain exceeds 32-bit bound')
        self.fields={};self.data=bytearray();self.launches={}
        def add(name,values,kind='d',mutable=False):
            self.data.extend(b'\xa5'*((-len(self.data))%8))
            self.fields[name]=dict(offset=len(self.data),count=len(values),kind=kind,mutable=mutable)
            self.data.extend(struct.pack('<'+kind*len(values),*values))
            # Guard each logical buffer, not just the outer allocation.
            self.data.extend(b'\xa5'*32)
        for key in ('B','D'):
            values=reference[key]
            if len(values)!=self.m**2 or not all(math.isfinite(x) for x in values):
                raise ValueError('invalid basis table')
            add(key,values)
        weights=reference['weights']
        if len(weights)!=self.m or not all(math.isfinite(w) and w>0 for w in weights):
            raise ValueError('invalid quadrature weights')
        add('W',[a*b for a in weights for b in weights])
        cells=reference['cells'];width=n*p+1
        expected=[[(ey*p+i)*width+ex*p+j for i in range(p+1) for j in range(p+1)]
                  for ey in range(n) for ex in range(n)]
        if cells!=expected:raise ValueError('connectivity is not the supported uniform mesh')
        add('cells',[j for row in cells for j in row],'I')
        bd=[int(i%width in (0,width-1) or i//width in (0,width-1)) for i in range(self.size)]
        if bd!=reference['boundary']:raise ValueError('boundary mask mismatch')
        add('boundary',bd,'I')
        incident=[[] for _ in range(self.size)]
        for e,cell in enumerate(cells):
            for i,node in enumerate(cell):incident[node].append(e*self.m**2+i)
        offsets=[0];entries=[]
        for xs in incident:
            entries.extend(xs);offsets.append(len(entries))
        add('offsets',offsets,'I');add('entries',entries,'I')
        for key in ('load','diagonal','probe'):
            values=reference[key]
            if len(values)!=self.size or not all(math.isfinite(x) for x in values):
                raise ValueError(f'invalid {key}')
            if key=='diagonal' and any(v<=0 for v,b in zip(values,bd) if not b):
                raise ValueError('Jacobi diagonal must be positive')
            add(key,values)
        rtol,atol=options.get('rtol',1e-10),options.get('atol',0.)
        if not all(type(v) in (int,float) and math.isfinite(v) and v>=0 for v in (rtol,atol)) or not(rtol or atol):
            raise ValueError('invalid tolerances')
        for k,minimum in (('maxiter',0),('check_every',1)):
            v=options.get(k,1000 if k=='maxiter' else 10)
            if type(v) is not int or v<minimum:raise ValueError(f'invalid {k}')
        add('rtol',[rtol]);add('atol',[atol])
        for key in ('x','rhs','r','z','p','ap','true_r','applied'):
            add(key,[0.]*self.size,mutable=True)
        add('element',[0.]*(n*n*self.m*self.m),mutable=True)
        for key in ('rho','rho_next','denominator','rr','rhs_square','true_square','rhs_norm','residual','tolerance','alpha','beta'):
            add(key,[0.],mutable=True)
        for key in ('active','broken','use_step'):add(key,[0],'I',mutable=True)

    def offset(self,name):return self.fields[name]['offset']
    def manifest(self):return dict(n=self.n,degree=self.p,bytes=len(self.data),fields=self.fields,launches=self.launches)

def validate_result(observed,ref,case):
    if observed['reason']!=ref['reason'] or observed['converged']!=ref['converged']:
        raise AssertionError(f"solve status differs: {observed['reason']} vs {ref['reason']}")
    metrics={
        'operator_max_absolute_difference':compare(observed['applied'],ref['applied'],2e-12,2e-12,'operator'),
        'solution_max_absolute_difference':compare(observed['solution'],ref['solution'],2e-11,2e-9,'solution')}
    if any(x!=0 for x,bd in zip(observed['solution'],ref['boundary'],strict=True) if bd):
        raise AssertionError('nonzero boundary solution')
    if observed['converged'] and not (math.isfinite(observed['true_residual_norm']) and observed['true_residual_norm']<=observed['tolerance']):
        raise AssertionError('false convergence')
    if case.get('maxiter')==0 and observed['iterations']!=0:raise AssertionError('maxiter=0 performed iterations')
    if case.get('source')=='polynomial' and case['degree']>=2:
        ideal=[x*(1-x)*y*(1-y) for x,y in ref['points']]
        metrics['polynomial_max_absolute_error']=compare(observed['solution'],ideal,2e-12,0,'polynomial')
    return metrics
